DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THECOVENANT' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THECOVENANT_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_1','The Covenant[NEWLINE]Mandatory Scripture recall with a conventional Faith and Culture economy[NEWLINE]Culture or a protected research economy[NEWLINE][NEWLINE]Protect population, production and borders while learning five passages. Written on the Heart adds +1 Culture per city. An unaided review earns 10 Faith and 5 Culture multiplied by the era index plus one, at most once per game turn, including examinations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_2','Recall Revelation before moving starting units. Study its five numbered sections aloud, hide the text, then enter the reference and every section in order. The next four introductions cover the remaining passages. Settle, explore and defend normally; a Scriptorium supplies 2 Faith and 1 Culture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_3','Tabernacles supply 3 Faith and 1 Science with the Temple cost, technology, maintenance and prerequisite building classes. Recall rewards supplement infrastructure. Successful unaided reviews expand intervals to 2, 4, 8 and 12 turns; at most one ordinary review occurs per turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_4','Use religious and cultural development for normal victory routes. Every tenth campaign turn requires all five passages in rotating order. Three consecutive unaided reviews mark mastery, but mastered passages remain in the review schedule. A failed or studied attempt resets that passage streak.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_5','- Frequent retrieval practice links references, exact wording and repeated reviews.[NEWLINE]- City Culture and early religious buildings support gradual economic development.[NEWLINE]- Successful unaided recall converts memory practice into useful era-scaled yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_6','- Mandatory recall interrupts play and provides no skip button.[NEWLINE]- Mistakes or studying forfeit that passage reward and shorten review spacing.[NEWLINE]- The civilization has no unique military unit or special combat advantage.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_7','- Pressure infrastructure and deny safe growth with ordinary military and diplomatic tools.[NEWLINE]- Protect exposed borders rather than treating memory rewards as military strength.[NEWLINE]- Compare sustained city yields and conventional research against individual recall payouts.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_8','- Recognising the displayed passage without rehearsing its reference and exact words.[NEWLINE]- Neglecting defense or population while concentrating exclusively on Faith generation.[NEWLINE]- Assuming mastery ends examinations or that each examination passage grants another reward.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: Safe development supports both economies; compare sustained city yields rather than individual recall rewards.[NEWLINE][NEWLINE]Children of the Kingdom: Both support religious development, while prayer and Grace remain distinct from Covenant word recall.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Triumphal Imperium: An under-defended border invites military pressure; recall rewards do not counter Victory Momentum.[NEWLINE][NEWLINE]The Boundless City: Compact territorial development can pressure conventional multiple cities; recall yields do not replace workforce infrastructure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_CIV_TEXT_10','The gate requires manual entry, tolerates case and punctuation in words, and compares reference components separately. Bulk insertion changes are rejected, but clipboard origin cannot be proven from EditBox text changes. Native keyboard dispatch, popup ordering and save-file continuation require in-game acceptance testing. See TheCovenant/docs/Testing.md.');
