INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_LEADER_TEXT_1','The Covenant[NEWLINE]Mandatory Scripture recall with a conventional Faith and Culture economy[NEWLINE]Culture or a protected research economy[NEWLINE][NEWLINE]Protect population, production and borders while learning five passages. Written on the Heart adds +1 Culture per city. An unaided review earns 10 Faith and 5 Culture multiplied by the era index plus one, at most once per game turn, including examinations.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_LEADER_TEXT_2','Recall Revelation before moving starting units. Study its five numbered sections aloud, hide the text, then enter the reference and every section in order. The next four introductions cover the remaining passages. Settle, explore and defend normally; a Scriptorium supplies 2 Faith and 1 Culture.[NEWLINE][NEWLINE]Tabernacles supply 3 Faith and 1 Science with the Temple cost, technology, maintenance and prerequisite building classes. Recall rewards supplement infrastructure. Successful unaided reviews expand intervals to 2, 4, 8 and 12 turns; at most one ordinary review occurs per turn.[NEWLINE][NEWLINE]Use religious and cultural development for normal victory routes. Every tenth campaign turn requires all five passages in rotating order. Three consecutive unaided reviews mark mastery, but mastered passages remain in the review schedule. A failed or studied attempt resets that passage streak.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THECOVENANT_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Pigeon Republic: Safe development supports both economies; compare sustained city yields rather than individual recall rewards.[NEWLINE][NEWLINE]Children of the Kingdom: Both support religious development, while prayer and Grace remain distinct from Covenant word recall.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Triumphal Imperium: An under-defended border invites military pressure; recall rewards do not counter Victory Momentum.[NEWLINE][NEWLINE]The Boundless City: Compact territorial development can pressure conventional multiple cities; recall yields do not replace workforce infrastructure.');
